begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select ok(not has_table_privilege('anon','public.privacy_authorizations','SELECT'),'Las autorizaciones no son públicas');
select ok(not has_table_privilege('authenticated','public.privacy_events','INSERT'),'El navegador no fabrica aceptaciones');
select ok(not has_table_privilege('service_role','public.privacy_events','UPDATE'),'El historial no se reescribe');
select ok(not has_function_privilege('authenticated','public.grant_privacy_authorization(uuid,text,text,text)','EXECUTE'),'Solo el servidor registra aceptación validada');
select ok(not has_function_privilege('anon','public.withdraw_privacy_authorization(uuid)','EXECUTE'),'La retirada verifica identidad en el servidor');
select ok(not has_function_privilege('authenticated','public.enforce_privacy_configuration(text)','EXECUTE'),'El navegador no cambia la configuración de otros usuarios');
select ok(not (select prosecdef from pg_proc where oid='public.grant_privacy_authorization(uuid,text,text,text)'::regprocedure),'La función no eleva privilegios');
insert into auth.users(id,aud,role,email) values
('00000000-0000-4000-8000-000000000061','authenticated','authenticated','mail061-a@example.invalid'),
('00000000-0000-4000-8000-000000000161','authenticated','authenticated','mail061-b@example.invalid');
create temporary table notice as select '{"version":"mail061-v1","identity":{"operator":"Synthetic SQL fixture"},"purpose":"Explicit test acceptance, never a commercial authorization"}'::text as body;
select ok(not public.privacy_authorization_valid('00000000-0000-4000-8000-000000000061'),'Registrarse no concede permiso');
select throws_ok($$insert into public.gmail_accounts(user_id,email,status,encrypted_refresh_token,scope_set) values('00000000-0000-4000-8000-000000000061','mail061-a@example.invalid','CONNECTED','test',array['https://www.googleapis.com/auth/gmail.readonly','https://www.googleapis.com/auth/gmail.compose'])$$,'P0001','PRIVACY_CONSENT_REQUIRED','OAuth no permite omitir la información previa');
select throws_ok($$select public.grant_privacy_authorization('00000000-0000-4000-8000-000000000061','old',repeat('a',64),(select body from notice))$$,'P0001','INVALID_INPUT','No registra versiones antiguas');
select throws_ok($$select public.grant_privacy_authorization('00000000-0000-4000-8000-000000000061','mail061-v1',repeat('a',64),(select body from notice))$$,'P0001','INVALID_INPUT','Valida la integridad del texto');
select ok(public.grant_privacy_authorization('00000000-0000-4000-8000-000000000061','mail061-v1',encode(digest((select body from notice),'sha256'),'hex'),(select body from notice)),'Aceptación explícita registrada');
select ok(public.privacy_authorization_valid('00000000-0000-4000-8000-000000000061'),'La autorización es válida');
select ok(not public.privacy_authorization_valid('00000000-0000-4000-8000-000000000061',repeat('b',64)),'Un cambio del texto exige nueva aceptación');
select ok(not public.privacy_authorization_valid('00000000-0000-4000-8000-000000000161'),'Otro usuario sigue sin permiso');
select ok(public.grant_privacy_authorization('00000000-0000-4000-8000-000000000061','mail061-v1',encode(digest((select body from notice),'sha256'),'hex'),(select body from notice)),'Reintentar la aceptación es idempotente');
select is((select count(*) from public.privacy_events where user_id='00000000-0000-4000-8000-000000000061'),1::bigint,'No fabrica aceptaciones duplicadas');
insert into public.gmail_accounts(id,user_id,email,status,encrypted_refresh_token,scope_set) values('10000000-0000-4000-8000-000000000061','00000000-0000-4000-8000-000000000061','mail061-a@example.invalid','CONNECTED','test',array['https://www.googleapis.com/auth/gmail.readonly','https://www.googleapis.com/auth/gmail.compose']);
update public.user_settings set automation_enabled=true where user_id='00000000-0000-4000-8000-000000000061';
select ok(public.gmail_execution_allowed('00000000-0000-4000-8000-000000000061','10000000-0000-4000-8000-000000000061'),'Permiso y automatización habilitan el trabajo');
select public.set_generation_retention('00000000-0000-4000-8000-000000000061','10000000-0000-4000-8000-000000000061',true,24,'mail056-v1');
insert into public.email_jobs(user_id,gmail_account_id,thread_id,target_message_id) values('00000000-0000-4000-8000-000000000061','10000000-0000-4000-8000-000000000061','thread061','message061');
select ok(public.withdraw_privacy_authorization('00000000-0000-4000-8000-000000000061'),'Retira la autorización');
select ok(not public.privacy_authorization_valid('00000000-0000-4000-8000-000000000061'),'La retirada es efectiva');
select is((select status from public.gmail_accounts where user_id='00000000-0000-4000-8000-000000000061'),'PAUSED','Pausa Gmail');
select ok(not public.gmail_execution_allowed('00000000-0000-4000-8000-000000000061','10000000-0000-4000-8000-000000000061'),'No permite nuevas generaciones');
select is((select status from public.email_jobs where user_id='00000000-0000-4000-8000-000000000061'),'SKIPPED','Cancela trabajos pendientes');
select is((select count(*) from public.generation_content_authorizations where user_id='00000000-0000-4000-8000-000000000061'),0::bigint,'Retira los permisos opcionales');
select throws_ok($$update public.gmail_accounts set status='CONNECTED' where user_id='00000000-0000-4000-8000-000000000061'$$,'P0001','PRIVACY_CONSENT_REQUIRED','No se puede reactivar sin una nueva autorización');
select public.withdraw_privacy_authorization('00000000-0000-4000-8000-000000000061');
select is((select count(*) from public.privacy_events where user_id='00000000-0000-4000-8000-000000000061'),2::bigint,'La retirada repetida no duplica eventos');
select public.grant_privacy_authorization('00000000-0000-4000-8000-000000000061','mail061-v1',encode(digest((select body from notice),'sha256'),'hex'),(select body from notice));
update public.gmail_accounts set status='CONNECTED' where user_id='00000000-0000-4000-8000-000000000061';
select ok(public.enforce_privacy_configuration(repeat('c',64)),'Comprueba la configuración vigente antes del trabajo');
select is((select status from public.gmail_accounts where user_id='00000000-0000-4000-8000-000000000061'),'PAUSED','Un aviso desactualizado pausa también los trabajos sin proveedor');
select ok((select withdrawn_at is null from public.privacy_authorizations where user_id='00000000-0000-4000-8000-000000000061'),'Un cambio de configuración no inventa una retirada del usuario');
delete from auth.users where id='00000000-0000-4000-8000-000000000061';
select is((select count(*) from public.privacy_events where user_id='00000000-0000-4000-8000-000000000061'),0::bigint,'El borrado de cuenta suprime también los registros de privacidad');
select * from finish();
rollback;
